    description:
      "Сменные продольно-резательные ножи для нетканых материалов спанбонд, мелтблаун и SMS. Варианты M2 HSS , D2 или твердого сплава с индивидуальными профилями и покрытиями для конкретного применения.",
    fullDescription:
      "Просечка нетканого материала представляет собой принципиально иную задачу, чем при обработке пленки или бумаги: материал не имеет направления зерен, имеет низкую прочность на разрыв в поперечном направлении и рыхлую волокнистую структуру, которая может истираться, деформироваться или расслаиваться на краю просечки, если геометрия ножа не соответствует структуре ткани и натяжению линии.\n\nНожи для продольной резки нетканых материалов Sureay изготавливаются из быстрорежущей стали M2 со специальной геометрией угла сгребания, разработанной специально для материалов с рыхлой структурой спанбонд, мелтблаун и гидроентанглизированных материалов. Оптимизированный положительный угол скалывания чисто срезает пучки волокон, а не сдвигает их в сторону, устраняя обтрепанные края и ворсинки волокон, которые являются причиной брака по качеству на линиях по переработке детских подгузников, женской гигиены и хирургических штор.\n\n## Типы нетканых материалов\n\n**Спанбонд ПП (структуры S, SS, SSS):** Наиболее распространенная нетканая основа. Выпускается в плотности 8-120 GSM. Стандартный M2 HSS при Ra ≤ 0,4 мкм поверхности, положительный наклон 15°-20°. Используется для производства гигиенических впитывающих изделий, рулонного геотекстиля и сельскохозяйственной мульчирующей пленки.\n\n**Сверхтонкие слои волокон (диаметр 1-5 мкм), используемые в качестве фильтрующей основы в респираторах N95/FFP2 и хирургических масках. Очень хрупкие и чувствительные к боковым растягивающим нагрузкам. Требуется пониженная скорость резки (60-100 м/мин), корпус ножа с малой массой для минимизации вибрации и покрытия от электростатического разряда (ESD) для предотвращения притягивания волокон к поверхности ножа.\n\n*медицинские ткани *SMS / SMMS:** Композит спанбонд-мелтблаун-спанбонд, используемый для изготовления хирургических халатов, занавесок и стерилизационных оберток. Для производства SMS медицинского класса требуется проверенное оборудование - мы предоставляем сертификаты материалов и отчеты о размерах, прослеживаемые по номеру партии, для соблюдения нормативных требований.\n\n**Нетканые материалы с гидротангенциальным/мокрым начесом:** Ткани с большим весом основы (50-200 GSM) и более плотной структурой. По своим режущим свойствам близка к пенопласту или бумаге - стандартные ножи из стали D2 или 52100 хорошо справляются с такими материалами.\n\n## Опция ESD-покрытия\n\nДля резки фильтровальных материалов, изготовленных методом мельтблоун и электропрядения, предусмотрена обработка поверхности ESD (электростатический разряд), которая предотвращает накопление статического заряда на поверхности ножа. Накопление статического заряда приводит к тому, что легкие волокна (особенно ПП, выдутый из расплава, с плотностью <15 GSM) прилипают к лезвию и в виде загрязнений переносятся на кромку рулона.",
